-size:.82rem;color:#7a5a4a;line-height:1.4}.abm .abm-devise{margin:3rem auto 0;max-width:760px;text-align:center;font-size:clamp(1.25rem,2.4vw,1.7rem);font-style:italic;color:var(--sang)}.abm .abm-devise::before,.abm .abm-devise::after{content:"—";margin:0 .6rem;color:var(--or)}/* emblèmes */.abm .abm-emb{display:grid;grid-template-columns:repeat(3,1fr);gap:1.1rem;margin:2.4rem 0}.abm .abm-carte{perspective:1000px;height:230px}.abm .abm-flip{position:relative;width:100%;height:100%;transform-style:preserve-3d;transition:transform .9s cubic-bezier(.2,.8,.2,1)}.abm .abm-carte:hover .abm-flip,.abm .abm-carte:focus-within .abm-flip{transform:rotateY(180deg)}.abm .abm-f,.abm .abm-v{position:absolute;inset:0;backface-visibility:hidden;border-radius:18px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:1.2rem}.abm .abm-f{background:linear-gradient(160deg,#7a1a1c,#4a0f12);border:1px solid rgba(214,166,64,.5);color:#fff}.abm .abm-f svg{width:84px;height:84px;margin-bottom:.8rem}.abm .abm-f b{font-size:1.3rem}.abm .abm-f small{color:var(--or2);letter-spacing:.12em;text-transform:uppercase;font-size:.72rem}.abm .abm-v{transform:rotateY(180deg);background:var(--or);color:var(--pourpre)}.abm .abm-v b{font-size:1.6rem}.abm .abm-v span{font-size:.92rem;margin-top:.4rem}.abm .abm-perils{display:flex;flex-wrap:wrap;gap:.6rem;margin-top:1.6rem}.abm .abm-perils span{padding:.55rem 1rem;border-radius:99px;background:rgba(255,255,255,.07);border:1px solid rgba(214,166,64,.35);font-size:.85rem;color:#f2e2cf}.abm .abm-perils span b{color:var(--or2);margin-right:.35rem}.abm .abm-sceau{float:right;margin:0 0 1rem 1.5rem;width:130px;height:130px;border-radius:50%;display:grid;place-items:center;text-align:center;border:2px dashed var(--or);color:var(--or2);font-weight:800;line-height:1.1;animation:abmTourne 40s linear infinite}.abm .abm-sceau span{display:block;animation:abmTourne 40s linear infinite reverse}.abm .abm-sceau b{display:block;font-size:2rem}/* musée */.abm .abm-mus{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(2rem,5vw,4rem);align-items:center}.abm .abm-img{position:relative;border-radius:22px;overflow:hidden;aspect-ratio:3/4;box-shadow:0 30px 60px -28px rgba(74,15,18,.6)}.abm .abm-img img{width:100%;height:100%;object-fit:cover;display:block;transform:scale(1.1);transition:transform 2s cubic-bezier(.16,.84,.24,1)}.abm .abm-img.is-in img{transform:scale(1.01)}.abm .abm-img figcaption{position:absolute;left:1rem;bottom:1rem;padding:.4rem .85rem;border-radius:99px;background:rgba(43,18,16,.75);color:#fff;font-size:.75rem}.abm .abm-kpi{display:grid;grid-template-columns:repeat(3,1fr);gap:.9rem;margin:1.6rem 0 0}.abm .abm-k{padding:1.1rem;border-radius:16px;background:#fff;border-top:4px solid var(--sang);box-shadow:0 14px 30px -22px rgba(74,15,18,.5)}.abm .abm-k b{display:block;font-size:1.9rem;font-weight:800;color:var(--sang);line-height:1;font-variant-numeric:tabular-nums}.abm .abm-k span{font-size:.84rem;color:#6d4f42}.abm .abm-band{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:2.6rem}.abm .abm-band figure{margin:0;border-radius:18px;overflow:hidden;aspect-ratio:16/10;position:relative}.abm .abm-band img{width:100%;height:100%;object-fit:cover;display:block;transition:transform 1.6s cubic-bezier(.16,.84,.24,1)}.abm .abm-band figure:hover img{transform:scale(1.08)}.abm .abm-band figcaption{position:absolute;left:1rem;bottom:.8rem;color:#fff;font-size:.8rem;text-shadow:0 1px 8px rgba(0,0,0,.7)}@keyframes abmTourne{to{transform:rotate(360deg)}}@media (max-width:900px){.abm .abm-dyn{grid-template-columns:repeat(3,1fr);row-gap:2rem}.abm .abm-dyn::before{display:none}.abm .abm-emb,.abm .abm-kpi{grid-template-columns:1fr}.abm .abm-mus,.abm .abm-band{grid-template-columns:1fr}.abm .abm-sceau{float:none;margin:0 auto 1.5rem}}@media (max-width:520px){.abm .abm-dyn{grid-template-columns:1fr 1fr}}.abm .abm-med{width:128px;height:128px;overflow:hidden;background:#2a0a0c}.abm .abm-med img{width:100%;height:100%;object-fit:cover;border-radius:50%;display:block;transition:transform .8s cubic-bezier(.2,.8,.2,1)}.abm .abm-roi:hover .abm-med img{transform:scale(1.12)}.abm .abm-carte{height:340px}.abm .abm-f{justify-content:flex-end;overflow:hidden;padding:1.4rem}.abm .abm-f img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 20%;z-index:0;transition:transform 1.4s cubic-bezier(.2,.8,.2,1)}.abm .abm-carte:hover .abm-f img{transform:scale(1.08)}.abm .abm-f::after{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(180deg,rgba(42,8,10,0) 35%,rgba(42,8,10,.88) 100%)}.abm .abm-f b,.abm .abm-f small,.abm .abm-f em{position:relative;z-index:2}.abm .abm-f em{font-style:normal;font-size:.78rem;color:#f6e7c4;opacity:.9;margin-bottom:.3rem}.abm .abm-credit{margin:.4rem 0 0;font-size:.74rem!important;line-height:1.5;color:rgba(246,231,196,.7)!important;text-align:center}@media (max-width:520px){.abm .abm-med{width:108px;height:108px}}</style><section class="abm-fond-r abm-motif abm-ouv"><div class="abm-in"><div class="abm-cadre abm-rv"><p>À 140 km de Cotonou, douze rois ont bâti leur palais dans la même enceinte de terre. Leurs murs racontent, en bas-reliefs, l'histoire d'un royaume que la France a brûlé en 1892.</p></div><div class="abm-chiffres abm-rv"><div class="abm-ch"><b data-c="12">12</b><span>rois</span></div><div class="abm-ch"><b data-c="47" data-s=" ha">47 ha</b><span>d'enceinte</span></div><div class="abm-ch"><b>1985</b><span>patrimoine mondial</span></div></div></div></section><section class="abm-fond-c abm-chap"><div class="abm-in"><div class="abm-g"><div class="abm-rv"><span class="abm-kick">La dynastie</span><h2>Douze rois, une seule enceinte</h2><p>De 1625 à 1900, douze souverains se sont succédé à la tête du royaume du Danxomè. C'est la chronologie retenue par l'UNESCO, qui a inscrit le site sur la Liste du patrimoine mondial en 1985 au titre des critères iii et iv. Chaque roi, à l'exception d'Akaba qui disposait d'une enceinte séparée, a fait édifier son palais à l'intérieur du même périmètre de murs en bauge, en reprenant l'organisation de l'espace et les matériaux de ses prédécesseurs. Le résultat est un ensemble d'environ 47 hectares au cœur de la ville d'Abomey, département du Zou.</p></div><div class="abm-rv" style="padding-top:3.2rem"><p>Les noms qui structurent la visite sont ceux de Houegbadja, fondateur de la dynastie, d'Agadja, qui pousse le royaume vers la côte au XVIIIe siècle, puis de Ghézo, de Glèlè et de Béhanzin, dernier roi à régner avant la conquête française. Les dates des premiers règnes varient selon les travaux : la chronologie du XVIIe siècle repose sur des listes dynastiques et reste discutée par les historiens.</p><p>Le principe fondateur souvent cité par les traditions du palais, « que le royaume soit toujours fait plus grand », se lit encore dans la disposition des cours, hiérarchisées de l'extérieur vers le privé.</p></div></div><div class="abm-dyn grille"><div class="abm-roi abm-rv"><div class="abm-med"><img src="/assets/img/wikimedia/abomey-goho-houegbadja.webp" alt="Emblème de Houegbadja : le poisson et la nasse, bas-relief de la place Goho à Abomey" loading="lazy" decoding="async" width="360" height="360"></div><b>Houegbadja</b><span>fondateur de la dynastie</span></div><div class="abm-roi abm-rv"><div class="abm-med"><img src="/assets/img/wikimedia/abomey-goho-agadja.webp" alt="Emblème de Agadja : le navire européen, bas-relief de la place Goho à Abomey" loading="lazy" decoding="async" width="360" height="360"></div><b>Agadja</b><span>pousse le royaume vers la côte au XVIIIe siècle</span></div><div class="abm-roi abm-rv"><div class="abm-med"><img src="/assets/img/wikimedia/abomey-goho-ghezo.webp" alt="Emblème de Ghézo : le buffle, bas-relief de la place Goho à Abomey" loading="lazy" decoding="async" width="360" height="360"></div><b>Ghézo</b><span>son emblème : le buffle</span></div><div class="abm-roi abm-rv"><div class="abm-med"><img src="/assets/img/wikimedia/abomey-goho-glele.webp" alt="Emblème de Glèlè : le lion, bas-relief de la place Goho à Abomey" loading="lazy" decoding="async" width="360" height="360"></div><b>Glèlè</b><span>son emblème : le lion</span></div><div class="abm-roi abm-rv"><div class="abm-med"><img src="/assets/img/wikimedia/abomey-goho-behanzin.webp" alt="Emblème de Béhanzin : le requin et l’œuf, bas-relief de la place Goho à Abomey" loading="lazy" decoding="async" width="360" height="360"></div><b>Béhanzin</b><span>dernier roi avant la conquête</span></div></div><p class="abm-devise abm-rv">Que le royaume soit toujours fait plus grand</p></div></section><section class="abm-fond-r abm-chap"><div class="abm-in"><div class="abm-g"><div class="abm-rv"><span class="abm-kick">Les bas-reliefs</span><h2>Des murs qui servaient d'archives</h2><p>Le Danxomè n'écrivait pas son histoire : il la sculptait. Les bas-reliefs en terre polychrome qui couvrent les façades alignent des panneaux racontant scène par scène les faits d'un règne : batailles, alliances, proverbes.</p><p>Chaque roi possède son emblème, qui sert de signature visuelle. Le buffle pour Ghézo, le lion pour Glèlè, le requin pour Béhanzin. Un guide du site vous apprendra à les repérer d'un mur à l'autre : c'est le vrai intérêt de la visite, et on ne le trouve nulle part ailleurs sous cette forme.</p></div><div class="abm-rv"><div class="abm-sceau" aria-hidden="true"><span><b>17</b>nov. 1892</span></div><p>Le 17 novembre 1892, les troupes du colonel Dodds entrent dans Abomey. Les palais brûlent : la plupart des travaux attribuent l'incendie à Béhanzin lui-même, qui fuit plutôt que de livrer sa capitale intacte. Des objets royaux sont emportés en France. Le site figurait dès 1985 sur la Liste du patrimoine mondial en péril, après les tornades de 1975, 1977 et 1984, et n'en a été retiré qu'en 2007, après un long chantier de restauration.</p><div class="abm-perils"><span><b>1975 · 1977 · 1984</b>tornades</span><span><b>1985</b>inscrit et classé en péril</span><span><b>2007</b>retiré de la liste en péril</span></div></div></div><div class="abm-emb grille"><div class="abm-carte abm-rv" tabindex="0"><div class="abm-flip"><div class="abm-f"><img src="/assets/img/wikimedia/abomey-goho-ghezo-buffle.webp" alt="Le buffle de Ghézo, bas-relief de la place Goho à Abomey" loading="lazy" decoding="async" width="640" height="800"><em>Bas-relief, place Goho</em><b>Le buffle</b><small>Survolez</small></div><div class="abm-v"><b>Ghézo</b><span>Le buffle signe son règne d'un mur à l'autre</span></div></div></div><div class="abm-carte abm-rv" tabindex="0"><div class="abm-flip"><div class="abm-f"><img src="/assets/img/wikimedia/abomey-statue-glele-lion.webp" alt="Statue royale mi-homme mi-lion du roi Glèlè" loading="lazy" decoding="async" width="640" height="800"><em>Statue royale mi-homme mi-lion</em><b>Le lion</b><small>Survolez</small></div><div class="abm-v"><b>Glèlè</b><span>Le lion est l'emblème de son règne</span></div></div></div><div class="abm-carte abm-rv" tabindex="0"><div class="abm-flip"><div class="abm-f"><img src="/assets/img/wikimedia/abomey-statue-behanzin-requin.webp" alt="Statue royale mi-homme mi-requin du roi Béhanzin" loading="lazy" decoding="async" width="640" height="800"><em>Statue royale mi-homme mi-requin</em><b>Le requin</b><small>Survolez</small></div><div class="abm-v"><b>Béhanzin</b><span>Le requin, emblème du dernier roi</span></div></div></div></div></div></section><section class="abm-fond-c abm-chap"><div class="abm-in"><div class="abm-mus"><figure class="abm-img abm-rv"><img src="/assets/img/amazone-640x854.webp" alt="Statue d'une amazone du Danxomè" loading="lazy" decoding="async"><figcaption>Statue d'une amazone du Danxomè</figcaption></figure><div class="abm-rv"><span class="abm-kick">Le musée</span><h2>Le musée, le chantier et les 26 trésors</h2><p>Le musée historique d'Abomey occupe les palais de Ghézo et de Glèlè et conserve un millier d'objets : trônes, récades, portes sculptées, tentures appliquées.</p><p>L'ensemble du site est en chantier : réhabilitation de plusieurs palais et construction du MuRAD, Musée des rois et des amazones du Danxomè, appelé à accueillir les 26 œuvres restituées par la France en novembre 2021. Ces pièces ont été montrées à Cotonou lors de l'exposition Art du Bénin d'hier et d'aujourd'hui, de février à mai 2022, puis conservées au Palais de la Marina. À ce jour, elles ne sont donc pas exposées de façon permanente à Abomey.</p><div class="abm-kpi grille"><div class="abm-k abm-rv"><b data-c="1000">1 000</b><span>objets au musée historique</span></div><div class="abm-k abm-rv"><b data-c="26">26</b><span>œuvres restituées en 2021</span></div><div class="abm-k abm-rv"><b>MuRAD</b><span>musée des rois et des amazones, en chantier</span></div></div></div></div><div class="abm-band"><figure class="abm-rv"><img src="/assets/img/abomey-palais-1200x1200.webp" alt="Cour des palais royaux d'Abomey" loading="lazy" decoding="async"><figcaption>Une cour des palais royaux</figcaption></figure><figure class="abm-rv"><img src="/assets/img/abomey-basrelief-1200x900.webp" alt="Bâtiment des palais royaux d'Abomey" loading="lazy" decoding="async"><figcaption>Les murs en bauge des palais</figcaption></figure></div></div></section><script>(function(){var r=document.currentScript&&document.currentScript.closest('.abm');if(!r)return;if(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches)return;if(!('IntersectionObserver'in window))return;r.classList.add('abm-js');function anim(el){var v=parseFloat(el.getAttribute('data-c')),dec=(el.getAttribute('data-c').split('.')[1]||'').length,suf=el.getAttribute('data-s')||'',t0=null,d=1500;function f(t){if(!t0)t0=t;var k=Math.min(1,(t-t0)/d),e=1-Math.pow(1-k,3),x=v*e;el.textContent=(dec?x.toFixed(dec).replace('.',','):Math.round(x).toLocaleString('fr-FR').replace(/\u202f|\u00a0/g,' '))+suf;if(k<1)requestAnimationFrame(f);}requestAnimationFrame(f);}var io=new IntersectionObserver(function(es){es.forEach(function(e){if(!e.isIntersecting)return;e.target.classList.add('is-in');e.target.querySelectorAll('[data-c]').forEach(anim);io.unobserve(e.target);});},{threshold:.18});r.querySelectorAll('.abm-rv').forEach(function(el){var g=el.parentElement;if(g&&/grille/.test(g.className))el.style.transitionDelay=(Array.prototype.indexOf.call(g.children,el)*120)+'ms';io.observe(el);});})();</script></div><div class="page-section abm-galerie"><section class="section padd-top-md padd-bottom-md marg-top-none marg-bottom-none"><article class="section-layout-wrapper grid-container grid-default"><div class="grid_3col_tpl_01 grid-x medium-up-3 align-center align-stretch grid-padding-x grid-padding-y"><div class="cell">@endverbatim<x-media.figure
